"use client";

import React, { useState, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Upload, X, FileText, CheckCircle2, AlertCircle } from "lucide-react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

interface FileWithStatus {
    file: File;
    id: string;
    status: "pending" | "uploading" | "completed" | "error";
    progress: number;
}

interface NeomorphicFileUploadProps {
    onFilesSelected?: (files: File[]) => void;
    maxFiles?: number;
    accept?: string;
    className?: string;
}

export default function NeomorphicFileUpload({
    onFilesSelected,
    maxFiles = 5,
    accept = "*",
    className,
}: NeomorphicFileUploadProps) {
    const [files, setFiles] = useState<FileWithStatus[]>([]);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFiles = useCallback(
        (newFiles: FileList | File[]) => {
            const filteredFiles = Array.from(newFiles).filter((file) => {
                if (accept === "*") return true;
                const acceptedTypes = accept.split(",").map((t) => t.trim());
                return acceptedTypes.some((type) => {
                    if (type.startsWith(".")) {
                        return file.name.toLowerCase().endsWith(type.toLowerCase());
                    }
                    if (type.endsWith("/*")) {
                        return file.type.startsWith(type.replace("/*", ""));
                    }
                    return file.type === type;
                });
            });

            const updatedFiles = [...files];
            filteredFiles.forEach((file) => {
                if (updatedFiles.length < maxFiles) {
                    const id = Math.random().toString(36).substring(7);
                    updatedFiles.push({ file, id, status: "pending", progress: 0 });

                    simulateUpload(id);
                }
            });

            setFiles(updatedFiles);
            if (onFilesSelected) {
                onFilesSelected(updatedFiles.map((f) => f.file));
            }
        },
        [files, maxFiles, accept, onFilesSelected]
    );

    const simulateUpload = (id: string) => {
        setFiles((prev) =>
            prev.map((f) => (f.id === id ? { ...f, status: "uploading" } : f))
        );

        let progress = 0;
        const interval = setInterval(() => {
            progress += Math.random() * 30;
            if (progress >= 100) {
                progress = 100;
                clearInterval(interval);
                setFiles((prev) =>
                    prev.map((f) =>
                        f.id === id ? { ...f, status: "completed", progress: 100 } : f
                    )
                );
            } else {
                setFiles((prev) =>
                    prev.map((f) => (f.id === id ? { ...f, progress } : f))
                );
            }
        }, 500);
    };

    const removeFile = (id: string) => {
        setFiles((prev) => prev.filter((f) => f.id !== id));
    };

    const onDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const onDragLeave = () => {
        setIsDragging(false);
    };

    const onDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        if (e.dataTransfer.files) {
            handleFiles(e.dataTransfer.files);
        }
    };

    return (
        <div className={cn("w-full max-w-md mx-auto space-y-8 p-4", className)}>
            {/* Upload Zone */}
            <motion.div
                onClick={() => fileInputRef.current?.click()}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
                whileHover={{ scale: 1.01 }}
                whileTap={{ scale: 0.98 }}
                className={cn(
                    "relative cursor-pointer rounded-[2rem] p-12 transition-all duration-300",
                    "bg-zinc-50 dark:bg-zinc-900 border border-transparent",
                    "shadow-[12px_12px_24px_rgba(0,0,0,0.07),-12px_-12px_24px_rgba(255,255,255,1)]",
                    "dark:shadow-[12px_12px_24px_rgba(0,0,0,0.5),-8px_-8px_16px_rgba(255,255,255,0.03)]",
                    isDragging && "shadow-inner border-zinc-200 dark:border-zinc-800 scale-[0.99] bg-zinc-100/50 dark:bg-zinc-800/50"
                )}
            >
                <input
                    type="file"
                    ref={fileInputRef}
                    onChange={(e) => e.target.files && handleFiles(e.target.files)}
                    multiple={maxFiles > 1}
                    accept={accept}
                    className="hidden"
                />
                <div className="flex flex-col items-center justify-center space-y-6">
                    <motion.div
                        animate={isDragging ? { y: [0, -10, 0] } : { y: [0, -5, 0] }}
                        transition={{
                            duration: isDragging ? 0.5 : 2,
                            repeat: Infinity,
                            ease: "easeInOut",
                        }}
                        className={cn(
                            "p-5 rounded-full bg-zinc-50 dark:bg-zinc-900 transition-shadow",
                            "shadow-[6px_6px_12px_rgba(0,0,0,0.05),-6px_-6px_12px_rgba(255,255,255,1)]",
                            "dark:shadow-[4px_4px_8px_rgba(0,0,0,0.4),-4px_-4px_8px_rgba(255,255,255,0.02)]",
                            isDragging && "shadow-inner"
                        )}
                    >
                        <Upload className="w-10 h-10 text-zinc-400 dark:text-zinc-500" />
                    </motion.div>
                    <div className="text-center space-y-2">
                        <h3 className="text-xl font-bold tracking-tight text-zinc-800 dark:text-zinc-100">
                            {isDragging ? "Release to drop" : "Select files"}
                        </h3>
                        <p className="text-sm text-zinc-500 dark:text-zinc-400 max-w-[200px] mx-auto leading-relaxed">
                            Drag and drop files here or click to browse files
                        </p>
                    </div>
                </div>
            </motion.div>

            {/* File List */}
            <div className="space-y-4">
                <AnimatePresence mode="popLayout">
                    {files.map((fileObj) => (
                        <motion.div
                            key={fileObj.id}
                            initial={{ opacity: 0, x: -20, scale: 0.9 }}
                            animate={{ opacity: 1, x: 0, scale: 1 }}
                            exit={{ opacity: 0, x: 20, scale: 0.9 }}
                            className={cn(
                                "p-5 rounded-2xl bg-zinc-50 dark:bg-zinc-900 flex flex-col space-y-4",
                                "shadow-[8px_8px_16px_rgba(0,0,0,0.05),-8px_-8px_16px_rgba(255,255,255,1)]",
                                "dark:shadow-[8px_8px_16px_rgba(0,0,0,0.4),-4px_-4px_8px_rgba(255,255,255,0.02)]"
                            )}
                        >
                            <div className="flex items-center justify-between">
                                <div className="flex items-center space-x-4 overflow-hidden">
                                    <div className="p-2.5 rounded-xl bg-zinc-50 dark:bg-zinc-900 shadow-inner border border-zinc-100/50 dark:border-zinc-800/50">
                                        <FileText className="w-5 h-5 text-indigo-500 dark:text-indigo-400" />
                                    </div>
                                    <div className="flex flex-col min-w-0">
                                        <span className="text-sm font-bold text-zinc-700 dark:text-zinc-200 truncate leading-none mb-1">
                                            {fileObj.file.name}
                                        </span>
                                        <span className="text-[10px] font-medium text-zinc-400 dark:text-zinc-500 uppercase tracking-wider tabular-nums">
                                            {(fileObj.file.size / 1024).toFixed(1)} KB
                                        </span>
                                    </div>
                                </div>
                                <motion.button
                                    whileHover={{ scale: 1.1, rotate: 90 }}
                                    whileTap={{ scale: 0.9 }}
                                    onClick={() => removeFile(fileObj.id)}
                                    className="p-2 rounded-full text-zinc-400 dark:text-zinc-500 hover:text-red-500 dark:hover:text-red-400 transition-colors"
                                >
                                    <X className="w-4 h-4" />
                                </motion.button>
                            </div>

                            <div className="flex items-center space-x-4">
                                <div className="flex-1 h-2 rounded-full bg-zinc-200 dark:bg-zinc-800 overflow-hidden shadow-inner p-[1px]">
                                    <motion.div
                                        className={cn(
                                            "h-full rounded-full transition-colors duration-500",
                                            fileObj.status === "completed" ? "bg-emerald-500" : "bg-indigo-500"
                                        )}
                                        initial={{ width: 0 }}
                                        animate={{ width: `${fileObj.progress}%` }}
                                    />
                                </div>
                                <div className="shrink-0">
                                    {fileObj.status === "completed" ? (
                                        <motion.div
                                            initial={{ scale: 0, rotate: -45 }}
                                            animate={{ scale: 1, rotate: 0 }}
                                            className="p-1 rounded-full bg-emerald-50 dark:bg-emerald-900/30"
                                        >
                                            <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                                        </motion.div>
                                    ) : fileObj.status === "error" ? (
                                        <AlertCircle className="w-5 h-5 text-red-500" />
                                    ) : (
                                        <span className="text-xs font-black tabular-nums text-zinc-400 dark:text-zinc-500 w-10 text-right">
                                            {Math.round(fileObj.progress)}%
                                        </span>
                                    )}
                                </div>
                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        </div>
    );
}
